import React, { useState, useMemo } from 'react';
import { REGIONS, parseEventDate, getRegion } from '../data/timeline';
import EventDetailPage from './EventDetailPage';

const getEventType = (id, types) => (types || []).find(t => t.id === id) || { id, label: id, color: '#8a8680', bg: '#f2f0ec' };

// ── Era label ────────────────────────────────────────────────────
function eraLabel(year) {
  if (year === null || year === undefined || isNaN(year)) return 'Unknown date';
  if (year < -3000) return 'Prehistoric / early civilisation';
  if (year < -500)  return 'Ancient world (before 500 BCE)';
  if (year < 0)     return 'Classical antiquity (500–1 BCE)';
  if (year < 500)   return 'Late antiquity (1–500 CE)';
  if (year < 1000)  return 'Early medieval (500–1000)';
  if (year < 1500)  return 'Medieval (1000–1500)';
  if (year < 1800)  return 'Early modern (1500–1800)';
  if (year < 1900)  return 'Nineteenth century (1800–1900)';
  // 20th & 21st century: by decade
  if (year < 2000) {
    const decade = Math.floor(year / 10) * 10;
    return `${decade}s`;
  }
  if (year < 2100) {
    const decade = Math.floor(year / 10) * 10;
    return `${decade}s`;
  }
  return 'Future';
}

// ── Single event card ────────────────────────────────────────────
function EventCard({ event, book, onEdit, compact, eventTypes, onTagClick, onSelect }) {
  const region = getRegion(event.region);
  const evType = getEventType(event.type, eventTypes);
  const parsed = parseEventDate(event.dateRaw);
  const bookCount = (event.bookIds || []).length;

  return (
    <div
      style={{
        background: 'var(--paper-2)',
        border: `1px solid var(--paper-3)`,
        borderLeft: `3px solid ${region.color}`,
        borderRadius: 8,
        padding: compact ? '8px 12px' : '12px 14px',
        cursor: 'pointer',
        transition: 'border-color 0.12s, box-shadow 0.12s',
        position: 'relative',
      }}
      onClick={() => onSelect?.(event.id)}
      onMouseEnter={e => {
        e.currentTarget.style.borderColor = region.color + '88';
        e.currentTarget.style.boxShadow = 'var(--shadow-sm)';
        const el = e.currentTarget.querySelector('.ev-actions');
        if (el) el.style.opacity = '1';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.borderColor = 'var(--paper-3)';
        e.currentTarget.style.boxShadow = 'none';
        const el = e.currentTarget.querySelector('.ev-actions');
        if (el) el.style.opacity = '0';
      }}
    >
      {/* Top row */}
      {/* Badge row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap', paddingRight: 70 }}>
        <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 12, background: evType.bg + '33', color: evType.color, border: `1px solid ${evType.color}44`, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{evType.label}</span>
        <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 12, background: region.color + '22', color: region.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{region.label}</span>
        {bookCount > 0 && (
          <span style={{ fontSize: 10, color: 'var(--ink-4)', display: 'flex', alignItems: 'center', gap: 3 }}>
            {(event.bookIds || []).slice(0, 3).map(bid => { const b = books?.find(b => b.id === bid); return b ? <span key={bid} style={{ display: 'inline-block', width: 6, height: 6, borderRadius: '50%', background: b.color }} /> : null; })}
            <span style={{ fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{bookCount} book{bookCount !== 1 ? 's' : ''}</span>
          </span>
        )}
      </div>

      {/* Title */}
      <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--ink)', marginTop: 6, lineHeight: 1.4 }}>
        {event.title}
      </div>

      {/* Tags */}
      {event.tags?.length > 0 && (
        <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', marginTop: 6 }}>
          {event.tags.map(tag => (
            <button key={tag} onClick={e => { e.stopPropagation(); onTagClick?.(tag); }}
              style={{ fontSize: 10, padding: '2px 8px', borderRadius: 20, background: 'var(--paper-3)', color: 'var(--ink-3)', fontFamily: 'var(--font-mono)', border: 'none', cursor: 'pointer' }}
              onMouseEnter={e => { e.currentTarget.style.background = 'var(--accent-light)'; e.currentTarget.style.color = 'var(--accent)'; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'var(--paper-3)'; e.currentTarget.style.color = 'var(--ink-3)'; }}
              title="Compare books on this tag">#{tag} ⟷</button>
          ))}
        </div>
      )}

      {/* Hint */}
      <div style={{ fontSize: 10, color: 'var(--ink-4)', marginTop: 5, fontStyle: 'italic' }}>Click to open perspectives →</div>

      {/* Hover actions */}
      <div className="ev-actions" style={{ position: 'absolute', top: 8, right: 10, display: 'flex', gap: 4, opacity: 0, transition: 'opacity 0.15s' }}>
        <button onClick={e => { e.stopPropagation(); onEdit(event); }}
          style={{ fontSize: 10, padding: '2px 8px', borderRadius: 5, background: 'var(--paper-3)', color: 'var(--ink-2)', border: 'none', cursor: 'pointer' }}
          onMouseEnter={e => e.currentTarget.style.color = 'var(--accent)'}
          onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-2)'}>Edit</button>
      </div>
    </div>
  );
}

// ── Compare panel — two region columns at a pinned year ──────────
function ComparePanel({ events, books, pinnedYear, mode, regions, compareBooks, onClose }) {
  const windowSize = 50;
  const inWindow = events.filter(e => {
    const { year } = parseEventDate(e.dateRaw);
    return Math.abs(year - pinnedYear) <= windowSize;
  });

  const getEventBooks = (ev) => ev.bookIds || (ev.bookId ? [ev.bookId] : []);

  const columns = mode === 'book'
    ? (compareBooks.length > 0 ? compareBooks : books.map(b => b.id)).map(bid => ({ id: bid, book: books.find(b => b.id === bid) }))
    : regions.map(rid => ({ id: rid, reg: getRegion(rid) }));

  return (
    <div style={{ borderTop: '1px solid var(--paper-3)', background: 'var(--paper)', flexShrink: 0, maxHeight: 340, display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 20px 8px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <span style={{ fontSize: 11, fontWeight: 500, color: 'var(--ink-2)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          {mode === 'book' ? 'BOOKS' : 'REGIONS'} · ±50 years around {pinnedYear < 0 ? Math.abs(pinnedYear) + ' BCE' : pinnedYear}
        </span>
        <span style={{ fontSize: 11, color: 'var(--ink-4)' }}>· {inWindow.length} event{inWindow.length !== 1 ? 's' : ''}</span>
        <button onClick={onClose} style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--ink-4)', padding: '2px 8px', border: '1px solid var(--paper-3)', borderRadius: 5, cursor: 'pointer' }}>Close ✕</button>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '12px 20px', display: 'grid', gridTemplateColumns: `repeat(${Math.min(columns.length, 4)}, 1fr)`, gap: 12 }}>
        {columns.map(col => {
          const colEvents = mode === 'book'
            ? inWindow.filter(e => getEventBooks(e).includes(col.id)).sort((a, b) => parseEventDate(a.dateRaw).sortKey - parseEventDate(b.dateRaw).sortKey)
            : inWindow.filter(e => e.region === col.id).sort((a, b) => parseEventDate(a.dateRaw).sortKey - parseEventDate(b.dateRaw).sortKey);
          const accent = mode === 'book' ? col.book?.color || '#888' : col.reg?.color || '#888';
          const colLabel = mode === 'book' ? col.book?.title || 'Unknown' : col.reg?.label || col.id;
          return (
            <div key={col.id}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                <div style={{ width: 7, height: 7, borderRadius: '50%', background: accent }} />
                <span style={{ fontSize: 11, fontWeight: 500, color: accent, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {colLabel.length > 20 ? colLabel.slice(0, 20) + '…' : colLabel}
                </span>
                <span style={{ fontSize: 10, color: 'var(--ink-4)' }}>{colEvents.length}</span>
              </div>
              {colEvents.length === 0 ? (
                <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic' }}>No events in window</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {colEvents.map(ev => {
                    const parsed = parseEventDate(ev.dateRaw);
                    const evBooks = mode === 'region' ? getEventBooks(ev).map(id => books.find(b => b.id === id)).filter(Boolean) : [];
                    return (
                      <div key={ev.id} style={{ background: 'var(--paper-2)', border: `1px solid ${accent}33`, borderRadius: 6, padding: '8px 10px' }}>
                        <div style={{ fontSize: 10, color: accent, fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 3 }}>{parsed.display}</div>
                        <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.35, marginBottom: 3 }}>{ev.title}</div>
                        {ev.note && <div style={{ fontSize: 11, color: 'var(--ink-3)', lineHeight: 1.5, fontStyle: 'italic' }}>{ev.note.slice(0, 100)}{ev.note.length > 100 ? '…' : ''}</div>}
                        {mode === 'region' && evBooks.length > 0 && (
                          <div style={{ display: 'flex', gap: 4, marginTop: 5, flexWrap: 'wrap' }}>
                            {evBooks.map(b => <span key={b.id} style={{ fontSize: 10, display: 'flex', alignItems: 'center', gap: 3, color: 'var(--ink-4)' }}><div style={{ width: 5, height: 5, borderRadius: '50%', background: b.color }} />{b.title.slice(0, 16)}</span>)}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Main TimelineView ─────────────────────────────────────────────
export default function TimelineView({ events, books, eventTypes, onAdd, onEdit, onUpdate, onManageTypes }) {
  const [regionFilter, setRegionFilter] = useState([]);
  const [typeFilter, setTypeFilter] = useState([]);
  const [bookFilter, setBookFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [pinnedYear, setPinnedYear] = useState(null);
  const [compareRegions, setCompareRegions] = useState(['europe', 'middle-east']);
  const [showCompare, setShowCompare] = useState(false);
  const [compareMode, setCompareMode] = useState('region');
  const [compareBooks, setCompareBooks] = useState([]);
  const [pinInput, setPinInput] = useState('');
  const [compareTag, setCompareTag] = useState(null);
  const [activeEventId, setActiveEventId] = useState(null);
  const [collapsedEras, setCollapsedEras] = useState({});
  const toggleEra = (era) => setCollapsedEras(c => ({ ...c, [era]: !c[era] }));

  const toggleRegion = (id) => setRegionFilter(f => f.includes(id) ? f.filter(r => r !== id) : [...f, id]);
  const toggleType   = (id) => setTypeFilter(f => f.includes(id) ? f.filter(t => t !== id) : [...f, id]);
  const toggleCompareRegion = (id) => setCompareRegions(prev => prev.includes(id) ? prev.filter(r => r !== id) : [...prev, id]);
  const toggleCompareBook   = (id) => setCompareBooks(prev => prev.includes(id) ? prev.filter(b => b !== id) : [...prev, id]);

  const getEventBooks = (ev) => ev.bookIds || (ev.bookId ? [ev.bookId] : []);

  // Filter + sort
  const filtered = useMemo(() => {
    return events
      .filter(e => regionFilter.length === 0 || regionFilter.includes(e.region))
      .filter(e => typeFilter.length === 0 || typeFilter.includes(e.type))
      .filter(e => bookFilter === 'all' || getEventBooks(e).includes(bookFilter))
      .filter(e => !search || e.title.toLowerCase().includes(search.toLowerCase()) || e.tags?.some(t => t.includes(search.toLowerCase())))
      .sort((a, b) => parseEventDate(a.dateRaw).sortKey - parseEventDate(b.dateRaw).sortKey);
  }, [events, regionFilter, typeFilter, bookFilter, search]);

  // Group by era
  const grouped = useMemo(() => {
    const groups = {};
    filtered.forEach(e => {
      const { year } = parseEventDate(e.dateRaw);
      const era = eraLabel(year);
      if (!groups[era]) groups[era] = [];
      groups[era].push(e);
    });
    return groups;
  }, [filtered]);

  const handlePinYear = () => {
    const parsed = parseEventDate(pinInput);
    if (parsed.year !== 0 || pinInput === '0') {
      setPinnedYear(parsed.year);
      setShowCompare(true);
    }
  };

  // Show detail page when an event is selected
  const activeEvent = activeEventId ? events.find(e => e.id === activeEventId) : null;
  if (activeEvent) {
    return (
      <EventDetailPage
        event={activeEvent}
        books={books}
        eventTypes={eventTypes}
        onUpdate={(updated) => onUpdate(updated)}
        onBack={() => setActiveEventId(null)}
      />
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>

      {/* Top bar */}
      <div style={{ padding: '12px 20px 10px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 500 }}>Timeline</div>
            <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
              {filtered.length} event{filtered.length !== 1 ? 's' : ''} · sorted oldest to newest
            </div>
          </div>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search events…"
            style={{ marginLeft: 'auto', width: 170, padding: '6px 12px', fontSize: 12 }} />
          <button onClick={onAdd} style={{ fontSize: 12, padding: '6px 16px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper)', border: 'none', whiteSpace: 'nowrap' }}>
            + Add event
          </button>
        </div>

        {/* Filter row */}
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }}>
          {/* Region pills */}
          {REGIONS.map(r => (
            <button key={r.id} onClick={() => toggleRegion(r.id)} style={{
              fontSize: 10, padding: '2px 9px', borderRadius: 20,
              border: `1px solid ${regionFilter.includes(r.id) ? r.color : 'var(--paper-3)'}`,
              background: regionFilter.includes(r.id) ? r.color + '22' : 'transparent',
              color: regionFilter.includes(r.id) ? r.color : 'var(--ink-4)',
              fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer',
            }}>{r.label}</button>
          ))}

          <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />

          {/* Type pills */}
          {(eventTypes || []).map(t => (
            <button key={t.id} onClick={() => toggleType(t.id)} style={{
              fontSize: 10, padding: '2px 9px', borderRadius: 20,
              border: `1px solid ${typeFilter.includes(t.id) ? t.color : 'var(--paper-3)'}`,
              background: typeFilter.includes(t.id) ? t.bg + '33' : 'transparent',
              color: typeFilter.includes(t.id) ? t.color : 'var(--ink-4)',
              fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer',
            }}>{t.label}</button>
          ))}

          {/* Book filter */}
          <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />
          <select value={bookFilter} onChange={e => setBookFilter(e.target.value)}
            style={{ fontSize: 11, padding: '3px 24px 3px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)' }}>
            <option value="all">All books</option>
            {books.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}
          </select>

          <button onClick={onManageTypes} style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer', background: 'none', border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', marginLeft: 'auto' }}>Manage types</button>
          {(regionFilter.length > 0 || typeFilter.length > 0 || bookFilter !== 'all') && (
            <button onClick={() => { setRegionFilter([]); setTypeFilter([]); setBookFilter('all'); }}
              style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
              clear filters
            </button>
          )}
        </div>
      </div>

      {/* Compare controls */}
      <div style={{ padding: '8px 20px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 8, alignItems: 'center', flexShrink: 0, background: 'var(--paper-2)', flexWrap: 'wrap' }}>
        {/* Mode toggle */}
        <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 6, overflow: 'hidden' }}>
          {[['region','By region'],['book','By book']].map(([m, l]) => (
            <button key={m} onClick={() => setCompareMode(m)}
              style={{ fontSize: 11, padding: '4px 10px', border: 'none', background: compareMode === m ? 'var(--accent)' : 'transparent', color: compareMode === m ? 'var(--paper-card)' : 'var(--ink-3)', cursor: 'pointer', borderRight: m === 'region' ? '1px solid var(--paper-3)' : 'none' }}>
              {l}
            </button>
          ))}
        </div>

        <input value={pinInput} onChange={e => setPinInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handlePinYear()}
          placeholder='Pin a year, e.g. "490 BCE" or "1250"'
          style={{ fontSize: 12, padding: '4px 10px', borderRadius: 6, width: 190 }} />
        <button onClick={handlePinYear} style={{ fontSize: 11, padding: '4px 12px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper)', border: 'none', cursor: 'pointer' }}>Pin</button>

        {compareMode === 'region' ? (
          <>
            <span style={{ fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>Regions:</span>
            {REGIONS.map(r => (
              <button key={r.id} onClick={() => toggleCompareRegion(r.id)} style={{ fontSize: 10, padding: '2px 8px', borderRadius: 12, background: compareRegions.includes(r.id) ? r.color : 'transparent', color: compareRegions.includes(r.id) ? '#fff' : 'var(--ink-4)', border: `1px solid ${compareRegions.includes(r.id) ? r.color : 'var(--paper-3)'}`, fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer' }}>{r.label}</button>
            ))}
          </>
        ) : (
          <>
            <span style={{ fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>Books:</span>
            {books.map(b => (
              <button key={b.id} onClick={() => toggleCompareBook(b.id)} style={{ fontSize: 10, padding: '2px 8px', borderRadius: 12, display: 'flex', alignItems: 'center', gap: 4, background: compareBooks.includes(b.id) ? b.color + '22' : 'transparent', color: compareBooks.includes(b.id) ? b.color : 'var(--ink-4)', border: `1px solid ${compareBooks.includes(b.id) ? b.color : 'var(--paper-3)'}`, cursor: 'pointer' }}>
                <div style={{ width: 5, height: 5, borderRadius: '50%', background: compareBooks.includes(b.id) ? b.color : 'var(--ink-4)' }} />
                {b.title.slice(0, 18)}{b.title.length > 18 ? '…' : ''}
              </button>
            ))}
          </>
        )}

        {showCompare && <button onClick={() => setShowCompare(false)} style={{ fontSize: 10, color: 'var(--ink-4)', marginLeft: 4, border: '1px solid var(--paper-3)', borderRadius: 5, padding: '2px 8px', fontFamily: 'var(--font-mono)', fontStyle: 'normal', cursor: 'pointer' }}>hide</button>}
      </div>

      {/* Event feed */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 20px' }}>
        {filtered.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic' }}>
            No events yet — add your first timeline entry.
          </div>
        ) : (
          Object.entries(grouped).map(([era, eraEvents]) => (
            <div key={era} style={{ marginBottom: 28 }}>
              {/* Era header — collapsible */}
              <button onClick={() => toggleEra(era)}
                style={{ display: 'flex', alignItems: 'center', gap: 10, width: '100%', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 0', marginBottom: collapsedEras[era] ? 0 : 12, textAlign: 'left' }}>
                <span style={{ fontSize: 9, color: 'var(--ink-4)', display: 'inline-block', transition: 'transform 0.15s', transform: collapsedEras[era] ? 'rotate(0deg)' : 'rotate(90deg)' }}>▶</span>
                <div style={{ fontSize: 10, fontWeight: 600, color: 'var(--ink-4)', letterSpacing: '0.08em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal', whiteSpace: 'nowrap' }}>
                  {era}
                </div>
                <div style={{ flex: 1, height: '1px', background: 'var(--paper-3)' }} />
                <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{eraEvents.length}</span>
              </button>

              {/* Events within era */}
              {!collapsedEras[era] && (
              <div style={{ display: 'grid', gridTemplateColumns: '80px 1fr', gap: '0 12px' }}>
                {eraEvents.map((ev, i) => {
                  const parsed = parseEventDate(ev.dateRaw);
                  const book = books.find(b => b.id === ev.bookId);
                  return (
                    <React.Fragment key={ev.id}>
                      <div style={{ textAlign: 'right', paddingTop: 10, fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', lineHeight: 1.3 }}>
                        {parsed.display || '—'}
                      </div>
                      <div style={{ position: 'relative', paddingBottom: i < eraEvents.length - 1 ? 8 : 0 }}>
                        {i < eraEvents.length - 1 && (
                          <div style={{ position: 'absolute', left: -7, top: 18, bottom: -4, width: 1, background: 'var(--paper-3)' }} />
                        )}
                        <div style={{ position: 'absolute', left: -10, top: 14, width: 7, height: 7, borderRadius: '50%', background: getRegion(ev.region).color, border: '2px solid var(--paper)', flexShrink: 0 }} />
                        <EventCard event={ev} book={book} books={books} onEdit={onEdit} eventTypes={eventTypes} onTagClick={tag => setCompareTag(prev => prev === tag ? null : tag)} onSelect={setActiveEventId} />
                        {i < eraEvents.length - 1 && <div style={{ height: 8 }} />}
                      </div>
                    </React.Fragment>
                  );
                })}
              </div>
              )}
            </div>
          ))
        )}
      </div>

      {/* Compare panel */}
      {showCompare && pinnedYear !== null && (
        <ComparePanel
          events={events} books={books} pinnedYear={pinnedYear}
          mode={compareMode}
          regions={compareRegions}
          compareBooks={compareBooks}
          onClose={() => setShowCompare(false)}
        />
      )}

      {/* Book comparison by tag */}
      {compareTag && (
        <BookComparePanel events={events} books={books} tag={compareTag} onClose={() => setCompareTag(null)} />
      )}
    </div>
  );
}

// ── Book comparison panel ────────────────────────────────────────
// Shows all events sharing a tag, grouped by book source side by side
export function BookComparePanel({ events, books, tag, onClose }) {
  const tagged = events.filter(e => e.tags?.includes(tag) || e.title?.toLowerCase().includes(tag.toLowerCase()));
  const bookIds = [...new Set(tagged.flatMap(e => e.bookIds || (e.bookId ? [e.bookId] : [])))];
  const relatedBooks = bookIds.map(id => books.find(b => b.id === id)).filter(Boolean);

  if (relatedBooks.length === 0) return null;

  return (
    <div style={{ borderTop: '1px solid var(--paper-3)', background: 'var(--paper)', flexShrink: 0, maxHeight: 340, display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 20px 8px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <span style={{ fontSize: 11, fontWeight: 500, color: 'var(--ink-2)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          BOOK COMPARISON · #{tag}
        </span>
        <span style={{ fontSize: 11, color: 'var(--ink-4)' }}>· {tagged.length} event{tagged.length !== 1 ? 's' : ''} · {relatedBooks.length} book{relatedBooks.length !== 1 ? 's' : ''}</span>
        <button onClick={onClose} style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--ink-4)', padding: '2px 8px', border: '1px solid var(--paper-3)', borderRadius: 5, cursor: 'pointer', background: 'transparent' }}>Close ✕</button>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '12px 20px', display: 'grid', gridTemplateColumns: `repeat(${Math.min(relatedBooks.length, 4)}, 1fr)`, gap: 12 }}>
        {relatedBooks.map(book => {
          const bookEvents = tagged.filter(e => (e.bookIds || [e.bookId]).includes(book.id));
          return (
            <div key={book.id}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                <div style={{ width: 8, height: 8, borderRadius: '50%', background: book.color }} />
                <span style={{ fontSize: 11, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</span>
              </div>
              {bookEvents.length === 0 ? (
                <div style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic' }}>No events for this tag</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {bookEvents.map(ev => {
                    const parsed = parseEventDate(ev.dateRaw);
                    return (
                      <div key={ev.id} style={{ background: 'var(--paper-card)', border: `1px solid ${book.color}33`, borderRadius: 7, padding: '8px 10px' }}>
                        <div style={{ fontSize: 10, color: book.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 3 }}>{parsed.display || '—'}</div>
                        <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', marginBottom: ev.note ? 4 : 0, lineHeight: 1.35 }}>{ev.title}</div>
                        {ev.quote && <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', borderLeft: `2px solid ${book.color}55`, paddingLeft: 6, marginBottom: 4, lineHeight: 1.5 }}>"{ev.quote.slice(0, 100)}{ev.quote.length > 100 ? '…' : ''}"</div>}
                        {ev.note && <div style={{ fontSize: 11, color: 'var(--ink-2)', lineHeight: 1.5 }}>{ev.note.slice(0, 120)}{ev.note.length > 120 ? '…' : ''}</div>}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
